/* Importação de validades de documentos RH por XLSX, com prévia e vínculo por nome. */
(function(root){'use strict';
const RH=root.EngefexRH;if(!RH)return;
const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=x=>String(x??'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,' ').trim().toLowerCase();
const kind=x=>{const s=normalize(x).toUpperCase();if(!s)return null;if(/\bASO\b/.test(s))return 'ASO';if(s.includes('NR 35'))return 'NR-35';if(/\bPTA\b/.test(s))return 'PTA';if(s.includes('MUNK'))return 'MUNK';if(s.includes('SOLDA'))return 'SOLDA';if(s.includes('NR 06')||s.includes('NR06')||s==='EPI')return 'EPI / NR-06';if(s.includes('NR 18')||s.includes('NR18'))return 'NR-18';if(s.includes('NR 12')||s.includes('NR12'))return 'NR-12';if(s.includes('IMAGEM'))return 'USO DE IMAGEM';return null};
const iso=x=>{if(!x||x==='*')return '';if(/^\d{4}-\d{2}-\d{2}/.test(String(x)))return String(x).slice(0,10);if(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(String(x))){const [d,m,y]=String(x).split('/');return y+'-'+m.padStart(2,'0')+'-'+d.padStart(2,'0')}const n=Number(x);if(Number.isFinite(n)&&n>30000&&n<100000)return new Date(Date.UTC(1899,11,30)+Math.round(n)*86400000).toISOString().slice(0,10);return ''};
const letters=x=>{let n=0;for(const c of x)n=n*26+c.charCodeAt(0)-64;return n};
async function parse(file){if(!root.JSZip)throw Error('Biblioteca XLSX indisponível.');const zip=await root.JSZip.loadAsync(file);const xml=async p=>new DOMParser().parseFromString(await zip.file(p).async('string'),'application/xml');const ss=zip.file('xl/sharedStrings.xml')?Array.from((await xml('xl/sharedStrings.xml')).getElementsByTagName('si')).map(s=>Array.from(s.getElementsByTagName('t')).map(x=>x.textContent).join('')):[];const sheetName=Object.keys(zip.files).filter(k=>/^xl\/worksheets\/sheet\d+\.xml$/.test(k))[0];if(!sheetName)throw Error('Planilha sem dados');const doc=await xml(sheetName),rows=[];
for(const row of Array.from(doc.getElementsByTagName('sheetData')[0]?.getElementsByTagName('row')||[])){const cells={};for(const c of Array.from(row.getElementsByTagName('c'))){const key=(c.getAttribute('r')||'').match(/^[A-Z]+/)?.[0];if(!key)continue;const raw=c.getElementsByTagName('v')[0]?.textContent||'';cells[letters(key)]=c.getAttribute('t')==='s'?ss[Number(raw)]||'':c.getAttribute('t')==='inlineStr'?Array.from(c.getElementsByTagName('t')).map(x=>x.textContent).join(''):raw}rows.push({number:Number(row.getAttribute('r')||0),cells})}
let headers={},records=[],ignored=0;for(const row of rows){const name=String(row.cells[1]||'').trim(),sample=Object.entries(row.cells).filter(([col])=>+col>1&&+col<=10).map(([col,val])=>[+col,kind(val)]).filter(x=>x[1]);if((normalize(name)==='nome'||normalize(name)==='pedreiros'||(!name&&sample.length>=2))&&sample.length>=2){headers=Object.fromEntries(sample);continue}if(!name||name.toUpperCase()==='PEDREIROS'||!Object.keys(headers).length)continue;const docs=Object.entries(headers).map(([col,type])=>({type,due:iso(row.cells[col])})).filter(x=>x.due);if(!docs.length){ignored++;continue}records.push({name,docs,row:row.number})}if(!records.length)throw Error('Não encontrei datas de validade reconhecíveis na planilha.');return {records,ignored}}
const oldPage=RH.page;RH.page=function(s,screen){const html=oldPage(s,screen);if(screen!=='documents')return html;const panel='<section class="panel hr-panel hr-import-docs"><div class="panel-head"><div><h2>Importar validades por Excel</h2><p class="hr-panel-subtitle">Planilha ASO, NR-35, PTA, MUNK, SOLDA, NR-06, NR-18, NR-12 e Uso de Imagem.</p></div></div><div class="hr-doc-import-actions"><label class="button primary">Selecionar planilha XLSX<input type="file" id="hrDocumentsXlsx" accept=".xlsx" hidden></label><span>Importe os funcionários antes dos documentos. Linhas sem correspondência serão ignoradas.</span></div><div id="hrDocsImportStatus" role="status"></div></section>';return html.replace('<nav aria-label="Documentos ou pendências"',panel+'<nav aria-label="Documentos ou pendências"')};
const oldAttach=RH.attach;RH.attach=function(s,persist,render,notify){oldAttach(s,persist,render,notify);const input=document.getElementById('hrDocumentsXlsx');if(!input)return;input.onchange=async()=>{const status=document.getElementById('hrDocsImportStatus');if(!root.EngefexAccess?.canWrite('hr-documents')){notify('Você não tem permissão para importar documentos.');return}const file=input.files?.[0];if(!file)return;try{status.textContent='Lendo a planilha...';const parsed=await parse(file),staff=s.hrEmployees||[];if(!staff.length)throw Error('Importe primeiro os funcionários; o cadastro está vazio.');let matched=[],unmatched=[],ambiguous=[];for(const rec of parsed.records){const found=staff.filter(e=>normalize(e.name)===normalize(rec.name));if(found.length===1)matched.push({...rec,employeeId:found[0].id});else (found.length?'ambiguous':'unmatched')==='ambiguous'?ambiguous.push(rec):unmatched.push(rec)}const nDocs=matched.reduce((t,r)=>t+r.docs.length,0);status.innerHTML='<p><strong>'+matched.length+' funcionários encontrados</strong> · '+nDocs+' validades · '+unmatched.length+' nomes não encontrados'+(ambiguous.length?' · '+ambiguous.length+' ambíguos':'')+'.</p>'+(unmatched.length?'<details><summary>Ver nomes sem correspondência</summary><p>'+unmatched.map(x=>escape(x.name)).join('; ')+'</p></details>':'');if(!matched.length)throw Error('Nenhum funcionário da planilha foi encontrado no cadastro.');if(!confirm('Importar '+nDocs+' validades para '+matched.length+' funcionários? '+unmatched.length+' pessoa(s) sem cadastro serão ignoradas. Registros com mesmo funcionário e tipo serão atualizados.'))return;const next=structuredClone(s);next.hrDocuments=next.hrDocuments||[];let created=0,updated=0;for(const rec of matched)for(const item of rec.docs){const prior=next.hrDocuments.find(d=>d.employeeId===rec.employeeId&&d.type===item.type);if(prior){if(prior.due!==item.due){prior.history=[...(prior.history||[]),{issued:prior.issued||'',due:prior.due||'',recordedAt:new Date().toISOString()}];prior.due=item.due;updated++}}else{next.hrDocuments.push({id:crypto.randomUUID(),employeeId:rec.employeeId,type:item.type,issued:'',due:item.due,history:[]});created++}}const result=await persist(next,'Validades importadas no Supabase.');if(result===false)throw Error('O banco não confirmou a importação.');notify('Importação concluída: '+created+' novos e '+updated+' atualizados.');render()}catch(err){status.textContent=err.message||'Falha ao importar';notify(err.message||'Falha ao importar')}}};
})(window);